import { z } from "zod";

// Every setting comes from Railway variables. Parsed once at startup; a bad value fails the boot
// with a readable message instead of failing later in the middle of a review.
const Env = z.object({
  ROLE: z.enum(["api", "worker", "cron"]),
  DATABASE_URL: z.string().min(1),
  PORT: z.coerce.number().int().positive().default(3000),
  LOG_LEVEL: z.enum(["debug", "info", "warn", "error"]).default("info"),
  WORKER_CONCURRENCY: z.coerce.number().int().positive().default(3),
  MAX_REVIEWS_PER_ORG: z.coerce.number().int().positive().default(2),
  // Generated by .railway/railway.ts. The api needs both; worker and cron need ENCRYPTION_KEY.
  ADMIN_PASSWORD: z.string().min(12).optional(),
  ENCRYPTION_KEY: z.string().regex(/^[0-9a-f]{64}$/i, "must be 64 hex characters").optional(),
  // Public base URL of the api. Railway provides RAILWAY_PUBLIC_DOMAIN; PUBLIC_URL overrides it.
  PUBLIC_URL: z.url().optional(),
  RAILWAY_PUBLIC_DOMAIN: z.string().optional(),
  // ---- models (worker) ----
  // Keys for whichever providers you use. MODEL_SMALL/MODEL_LARGE default to GLM 5.3 with
  // OPENROUTER_API_KEY, or Haiku/Sonnet with only ANTHROPIC_API_KEY (src/llm/models.ts).
  OPENROUTER_API_KEY: z.string().optional(),
  ANTHROPIC_API_KEY: z.string().optional(),
  OPENAI_API_KEY: z.string().optional(),
  OPENAI_COMPATIBLE_API_KEY: z.string().optional(),
  OPENAI_COMPATIBLE_BASE_URL: z.url().optional(),
  MODEL_SMALL: z.string().optional(), // "provider:model"
  MODEL_LARGE: z.string().optional(),
  ALLOWED_MODELS: z.string().optional(), // comma-separated; what .selfreview.yml may choose
  SMALL_DIFF_LINES: z.coerce.number().int().positive().default(400), // below this, the small model
  MAX_REVIEW_COST_USD: z.coerce.number().positive().default(1),
  // Prices for models without a built-in or OpenRouter price, $ per 1M tokens, e.g.
  // {"openai:gpt-5-mini": {"input": 0.25, "output": 2, "cachedInput": 0.025}}
  MODEL_PRICES: z
    .string()
    .optional()
    .transform((text, ctx) => {
      if (!text) return {};
      try {
        return JSON.parse(text) as unknown;
      } catch {
        ctx.addIssue({ code: "custom", message: "must be JSON" });
        return z.NEVER;
      }
    })
    .pipe(
      z.record(
        z.string(),
        z.object({ input: z.number().nonnegative(), output: z.number().nonnegative(), cachedInput: z.number().nonnegative().optional() })
          .transform((p) => ({ ...p, cachedInput: p.cachedInput ?? p.input })),
      ),
    ),
  // A hard monthly cap on model spend. On by default so a fresh deploy can't run up a bill.
  MONTHLY_BUDGET_USD: z.coerce.number().positive().default(10),
  // ---- accounts (api) ----
  // GitHub users or orgs whose repos may be reviewed, besides the app's owner. Comma-separated.
  // Setting it also makes a newly created GitHub App public, so those accounts can install it.
  ALLOWED_ACCOUNTS: z
    .string()
    .default("")
    .transform((text) => text.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean)),
  // ---- updates (api) ----
  // Set by Railway for GitHub deploys. The dashboard compares it with UPDATE_REPO's main branch.
  RAILWAY_GIT_COMMIT_SHA: z.string().optional(),
  UPDATE_REPO: z.string().default("hackertron/selfreview"),
});

export type Config = z.infer<typeof Env>;

export function loadConfig(env: Record<string, string | undefined> = process.env): Config {
  // ROLE defaults to the Railway service name (api / worker / cron), so a template deploy
  // needs no per-service ROLE variable.
  const result = Env.safeParse({ ...env, ROLE: env.ROLE ?? env.RAILWAY_SERVICE_NAME });
  if (!result.success) throw new Error(`Invalid environment:\n${z.prettifyError(result.error)}`);
  return result.data;
}

export function publicUrl(config: Config): string {
  if (config.PUBLIC_URL) return config.PUBLIC_URL.replace(/\/$/, "");
  if (config.RAILWAY_PUBLIC_DOMAIN) return `https://${config.RAILWAY_PUBLIC_DOMAIN}`;
  return `http://localhost:${config.PORT}`;
}

export function required<K extends keyof Config>(config: Config, key: K): NonNullable<Config[K]> {
  const value = config[key];
  if (value === undefined || value === null || value === "") throw new Error(`${String(key)} must be set for ROLE=${config.ROLE}`);
  return value as NonNullable<Config[K]>;
}
